O que aparece no terminal?

```javascript
function dividir(total, pessoas) {
  if (pessoas < 1) {
    throw new Error('A conta precisa de pelo menos 1 pessoa.');
  }
  return total / pessoas;
}

try {
  console.log('A');
  console.log(dividir(100, 0));
  console.log('B');
} catch (erro) {
  console.log(erro.message);
}
console.log('C');
```

